/**
 * @file internal/server/ui/src/api.d.ts
 *
 * The API's shapes as TypeScript: one declaration per schema of
 * docs/api-v1-openapi.yaml (components.schemas), in the file's order.
 * Generated by tools/apitypes from the OpenAPI file; not edited by hand:
 * make api-types writes it again.
 */

export interface StoredBackup {
  id: number;
  /** @format date-time */
  taken_at: string;
  reason: "auto" | "manual" | "before_restore" | "upload";
  format: "json" | "yaml";
  /** The software that wrote the file */
  tool?: string;
  /** Bytes of the file */
  size: number;
  sha256: string;
  /** Who asked; absent for the server's own */
  user?: string;
  note?: string;
}

/**
 * A Cube row of the store that no runtime serves and that keeps backups, as GET
 * /api/v1/backups/unserved lists it
 */
export interface UnservedCube {
  serial: string;
  /** The row's name; absent where it has none */
  name?: string;
  /** The backups kept */
  backups: number;
  /**
   * When the newest backup was taken
   * @format date-time
   */
  newest: string;
}

export interface BackupList {
  backups: StoredBackup[];
  /**
   * When the configuration last changed against the newest backup; absent when
   * it did not
   * @format date-time
   */
  changed?: string;
  /**
   * When the automatic backup follows; absent when none is due
   * @format date-time
   */
  due?: string;
}

export interface Preference {
  key?: string;
  /** The JSON document as stored */
  value?: unknown;
  /** @format date-time */
  updated_at?: string;
  /** Counts the writes of the key; a later write wins */
  version?: number;
}

export interface PushSubscription {
  id: number;
  endpoint: string;
  label: string;
  /** @format date-time */
  created_at: string;
  /**
   * The last message the push service took; absent before the first
   * @format date-time
   */
  last_ok_at?: string;
  /** Failed deliveries since then */
  failures: number;
  /** Made with the caller's session or key */
  current: boolean;
}

/**
 * queued, the request is running and nothing went to the Cube yet; sent, a step
 * went to the Cube, or the request was answered 202 and its run goes on;
 * acknowledged, answered 2xx (a step: the Cube accepted it); failed, answered
 * 5xx (a step: the send failed); dropped, answered 4xx or 503, nothing sent (a
 * step: superseded, discarded by the Cube, or the server stopped).
 */
export type CommandState = "queued" | "sent" | "acknowledged" | "failed" | "dropped";

export interface Command {
  /** @format uuid */
  id?: string;
  /** As the audit names it */
  action?: string;
  target?: string;
  /** The Cube's serial */
  cube?: string;
  /** The login name of who asked */
  user?: string;
  state?: CommandState;
  /** The HTTP status answered; absent while running */
  status?: number;
  /** The method, the path, the query and a hash of the body */
  request?: Record<string, unknown>;
  /** The answer's body; for a restore, the run's id, state and counts */
  result?: Record<string, unknown>;
  /** @format date-time */
  created_at?: string;
  /** @format date-time */
  updated_at?: string;
  /** @format date-time */
  finished_at?: string;
  /** The engine commands of the request, in order */
  steps?: CommandStep[];
  /**
   * The request's audit row, for a caller with audit; absent for a proxy
   * client's command, which has none
   */
  audit?: AuditEntry;
}

export interface CommandStep {
  /** @format uuid */
  id?: string;
  /** device:0a010d or room:6 */
  target?: string;
  state?: CommandState;
  /**
   * The queue key, the priority, the number of lines and of radio lines, the
   * wakeup, the room
   */
  request?: Record<string, unknown>;
  /**
   * discarded, the budget the Cube reported, the error, answers (the Cube's
   * answer to each line, in order, up to the first failure) and discarded_line
   * (the line the Cube discarded)
   */
  result?: Record<string, unknown>;
  /** @format date-time */
  created_at?: string;
  /** @format date-time */
  finished_at?: string;
}

export interface AuditEntry {
  id?: number;
  /** @format date-time */
  time?: string;
  /**
   * The login name of the user whose rights it had; absent for no
   * authentication, a failed login or the command line
   */
  user?: string;
  effective_user?: RowUser;
  real_user?: RowUser;
  /** The session or key used */
  token_id?: number;
  /** The client's address, or cli */
  remote?: string;
  /**
   * setpoint, room.config, device.update, cube.add, user.add, login,
   * login.failed, …
   */
  action?: string;
  /** The Cube's serial, for a Cube's route */
  cube?: string;
  /** device:0a010d, room:6, user:anna, role:night, token:4, cube:KEQ0000000 */
  target?: string;
  /**
   * The method, the path, the status, the milliseconds, the body's size and,
   * when JSON and short, the body with password, current_password, token,
   * record, proof, login, ke1 and ke3 removed, and the error of a failed
   * answer. A request refused for a known user keeps no body. Requests refused
   * before anyone is known are one row per address and minute, without their
   * bodies: the first one's method, path and status, the count of requests
   * within the minute, the count of each status in statuses, and the time of
   * the last.
   */
  detail?: Record<string, unknown>;
  result?: "ok" | "refused" | "failed";
  /** The command the request is, when it is one */
  command_id?: number;
}

export interface UserCreate {
  /**
   * The login name: 1 to 64 of letters, digits, '.', '_', '-' and '@', case
   * does not matter
   */
  name: string;
  display_name?: string;
  /** A role's key; viewer when absent, owner for the first owner */
  role?: string;
  /**
   * 8 to 64 characters, Unicode code points as sent, without the user's or the
   * server's name. Absent for a user with keys only, and an empty one counts as
   * absent; this or record for the first owner
   */
  password?: string;
  /**
   * A password of auth_version 2 in place of password: the registration record,
   * base64url (POST /api/v1/users/{name}/register)
   */
  record?: string;
  /**
   * The record's key stretching, as the registration answered it:
   * m=<KiB>,t=<passes>,p=<lanes>
   */
  ksf?: string;
  disabled?: boolean;
  /**
   * Guests: disabled from then on
   * @format date-time
   */
  expires_at?: string;
}

export interface UserChange {
  display_name?: string;
  role?: string;
  disabled?: boolean;
  /**
   * null clears the end date
   * @format date-time
   */
  expires_at?: string | null;
  /**
   * Empty removes the password; any other has 8 to 64 characters, Unicode code
   * points as sent, without the user's or the server's name
   */
  password?: string;
  /** Required when a user sets its own password, unless proof is given */
  current_password?: string;
  /**
   * A password of auth_version 2 in place of password: the registration record,
   * base64url
   */
  record?: string;
  /** The record's key stretching: m=<KiB>,t=<passes>,p=<lanes> */
  ksf?: string;
  /**
   * A proof of the current password from POST /api/v1/login/finish with the
   * purpose proof, in place of current_password
   */
  proof?: string;
}

export interface Role {
  key: string;
  /** The display name; empty shows the key's translated default */
  name?: string;
  /** One of the six default roles, which keep their keys */
  builtin: boolean;
  disabled: boolean;
  /** The role's set, sorted; every capability for owner */
  capabilities?: string[];
  /** Users with this role */
  users: number;
  /** @format date-time */
  created_at: string;
  /** @format date-time */
  updated_at: string;
}

export interface RoleCreate {
  /**
   * 1 to 32 of letters, digits, '_' and '-', starting with a letter; lower case
   */
  key: string;
  name?: string;
  capabilities?: string[];
}

export interface RoleChange {
  name?: string;
  /** Replaces the set */
  capabilities?: string[];
}

export interface Capability {
  key: string;
  /** Denied to every role but owner */
  disabled: boolean;
}

export interface Disabled {
  disabled: boolean;
}

export interface Login {
  /** The login name; case does not matter */
  user: string;
  password: string;
  /** Names the session under the user's tokens; the User-Agent when absent */
  label?: string;
  /**
   * A sign-in by OPAQUE for the name, started from this address, that the
   * client could not finish: this request takes it over, so that the attempt
   * counts once, and answers upgrade for a user still of auth_version 1
   */
  login?: string;
}

export interface LoginStart {
  /** The login name; case does not matter */
  user: string;
  /** The client's KE1, 96 bytes, base64url without padding */
  ke1: string;
  /** A proof of the password in place of a session */
  purpose?: "proof";
}

export interface LoginStarted {
  /** The identifier to finish under */
  login?: string;
  /** The server's KE2, 320 bytes, base64url without padding */
  ke2?: string;
  /** The key stretching to run: argon2id m=<KiB>,t=<passes>,p=<lanes> */
  ksf?: string;
  /** The box takes POST /api/v1/login as well */
  v1?: boolean;
  /**
   * A minute from now
   * @format date-time
   */
  expires_at?: string;
}

export interface LoginFinish {
  login: string;
  /** The client's KE3, 64 bytes, base64url without padding */
  ke3: string;
  /** Names the session under the user's tokens; the User-Agent when absent */
  label?: string;
}

export interface Provider {
  key: string;
  /** On the sign-in button; the key shows where empty */
  name: string;
  issuer: string;
  client_id: string;
  /** The client secret is set; it is never answered */
  has_secret: boolean;
  /**
   * The client secret is set and sealed, and the key of opaque.key does not
   * open it: it is to be entered again
   */
  secret_lost: boolean;
  scopes: string;
  /** A sign-in without an identity creates the user */
  auto_create: boolean;
  /** The role of a user created so, viewer by default */
  auto_role: string;
  /** The e-mail domains it creates users for; none for any */
  auto_domains?: string[];
  /** The claim of the account's groups, groups by default */
  groups_claim: string;
  /**
   * The groups it admits: an account in none of them neither signs in nor
   * links; none for any
   */
  allowed_groups?: string[];
  enabled: boolean;
  /** The redirect URI's path under the page's address */
  callback: string;
  /** @format date-time */
  created_at: string;
  /** @format date-time */
  updated_at: string;
}

export interface ProviderWrite {
  /**
   * In POST: 1 to 32 of lower-case letters, digits, _ and -, starting with a
   * letter
   */
  key?: string;
  name?: string;
  issuer?: string;
  client_id?: string;
  /** Written only; "" clears it */
  client_secret?: string;
  /** Space-separated, openid among them; openid email profile by default */
  scopes?: string;
  auto_create?: boolean;
  auto_role?: string;
  auto_domains?: string[];
  /** groups where empty */
  groups_claim?: string;
  allowed_groups?: string[];
  enabled?: boolean;
}

export interface Identity {
  id: number;
  /** The provider's key */
  provider: string;
  /** Lower case */
  email: string;
  /** The user id at the provider (sub); empty until bound */
  subject: string;
  /** The identity has the provider's subject */
  bound: boolean;
  /** The name at the provider, from the last sign-in or link */
  name: string;
  /** The user name at the provider (preferred_username), likewise */
  username: string;
  /** The groups at the provider, likewise */
  groups?: string[];
  /** @format date-time */
  created_at: string;
  /** @format date-time */
  bound_at?: string;
  /** @format date-time */
  last_used_at?: string;
}

export interface PendingLink {
  /** The provider's key */
  provider: string;
  provider_name: string;
  /** The user id at the provider */
  subject: string;
  email: string;
  name: string;
  username: string;
  groups?: string[];
  /** The user's identities at the provider the link replaces */
  replaces?: Identity[];
  /** @format date-time */
  expires_at: string;
}

/** The provider and either email or subject. */
export interface IdentityAdd {
  provider: string;
  email?: string;
  /** The user id at the provider (sub) */
  subject?: string;
}

export interface LoginProvider {
  key: string;
  /** On the sign-in button; the key where the provider has none */
  name: string;
}

export interface OIDCStart {
  /** The page's own address, http or https, without a query or fragment */
  redirect: string;
}

export interface OIDCStarted {
  /** The provider's authorization URL, to open in the browser */
  url?: string;
  /**
   * Ten minutes from now
   * @format date-time
   */
  expires_at?: string;
}

export interface OIDCFinish {
  /** The callback's #oidc= code */
  code: string;
  /** Names the session under the user's tokens; the User-Agent when absent */
  label?: string;
}

export interface Proof {
  /** Good once, for PUT /api/v1/users/{name} of one's own password */
  proof?: string;
  /**
   * Five minutes from now
   * @format date-time
   */
  expires_at?: string;
}

export interface Register {
  /** The client's registration request, 32 bytes, base64url without padding */
  request: string;
}

export interface Registered {
  /** The server's registration response, 64 bytes, base64url without padding */
  response?: string;
  /** The key stretching to run and to send with the record */
  ksf?: string;
}

export interface Session {
  /** The session token, shown once; sent as the bearer header */
  token?: string;
  /**
   * 30 days from now, moved by use
   * @format date-time
   */
  expires_at?: string;
  user?: User;
  role?: RoleRef;
  /**
   * The effective set, with what it includes: restart beside update or reboot
   */
  capabilities?: string[];
  /**
   * With login, for a user of auth_version 1: a proof, good once for five
   * minutes, to set the user's own record with in PUT /api/v1/users/{name}
   * without the password
   */
  upgrade?: string;
  /** After a sign-in through an OpenID Connect provider: the provider's key */
  provider?: string;
}

/**
 * A user of a row of the log or the audit, as it is named now: effective_user
 * the user whose rights it had, real_user who made it, the same user but for a
 * call of an integration's user linked to a Massimo user, which the effective
 * user then is. Absent for no authentication, the Cube and the server's own
 * jobs.
 */
export interface RowUser {
  /**
   * The login name; an integration's user's is <the integration's uuid>:<its id
   * there>
   */
  name?: string;
  display_name?: string;
  /** The uuid of the integration whose user it is; absent for any other user */
  integration?: string;
  /**
   * How it is shown: its display name, else its login name; an integration's
   * user by the chain "<the integration's name> › <its display name>";
   * real_user's with ", as <the effective user's login name>" where the two
   * differ.
   */
  display?: string;
}

export interface User {
  /**
   * The login name, lower case; an integration's users' are <the integration's
   * uuid>:, <uuid>:system and <uuid>:<its id there>
   */
  name: string;
  display_name?: string;
  /**
   * How the user is shown: its display name, else its login name; an
   * integration's user by the chain "<the integration's name> › <its display
   * name>", with ", as <login name>" where it is linked to a Massimo user
   */
  display?: string;
  /** The role's key */
  role: string;
  disabled: boolean;
  /** False for a user with keys only */
  has_password: boolean;
  /**
   * Guests: disabled from then on
   * @format date-time
   */
  expires_at?: string;
  /** The user that created this one */
  invited_by?: string;
  /**
   * 1: the server hashes the password; 2: OPAQUE, the server keeps a record and
   * never sees the password
   */
  auth_version: number;
  /** @format date-time */
  created_at: string;
  /** @format date-time */
  updated_at: string;
  /** @format date-time */
  last_login_at?: string;
  /**
   * In the users routes' answers: what the caller may do with the user, change
   * it beyond its own name and password (manage) or set its password
   * (password), the roles it may give it (roles), and whether its role as
   * stored lies beyond its integration's maximum (beyond); absent elsewhere
   */
  may?: {
    manage: boolean;
    password: boolean;
    /**
     * An integration's user's role, as stored, lies beyond the role integration
     * and its integration's maximum, within which it acts all the same; false
     * for every other user. A role that roles leaves out may lie within them
     * and be one the caller does not outrank
     */
    beyond: boolean;
    /**
     * The keys of the roles the caller may give the user, in the roles' order,
     * empty where it may give none; of those, for an integration's user only
     * the roles within the role integration and its integration's maximum, and
     * integration itself, never owner. A holder of users without roles or
     * integrations learns from it the keys of the roles it outranks and, for
     * each integration's user, which of them lie within that integration's
     * maximum
     */
    roles: string[];
  };
  /**
   * An integration's user, with its integration's uuid; in GET /api/v1/users
   * id, name and linked_to for one of its users, absent for the integration's
   * own
   */
  integration?: {
    uuid?: string;
    id?: string;
    name?: string;
    linked_to?: string;
  };
  /** In GET /api/v1/users: the integrations' users linked to this user */
  links?: {
    /** The integration's uuid */
    integration?: string;
    id?: string;
    name?: string;
    /** Its chain, <the integration's name> › <its display name> */
    display?: string;
  }[];
}

export interface UserCreated extends User {
  open_setup?: OpenSetup;
}

/**
 * What was set up before the first regular user and still works, for the first
 * owner to check, as a rule while the server was open, else left by an owner
 * since removed: in the first owner's answer of POST /api/v1/users alone, where
 * it holds anything; each list absent where empty. Names only, never a key or a
 * secret
 */
export interface OpenSetup {
  /**
   * The integrations active with a live key, or one still to be collected with
   * the approval's code; requests still waiting are not listed
   */
  integrations?: {
    uuid: string;
    /** The name the owner gave it, else the one it reports */
    name: string;
  }[];
  /** The sign-in providers enabled */
  providers?: {
    key: string;
    /** The name on its button; absent shows the key */
    name?: string;
    /** A sign-in without an identity creates the user */
    auto_create?: boolean;
  }[];
  /**
   * The roles added, and the default ones changed or disabled; never owner or
   * integration
   */
  roles?: {
    key: string;
    /** The display name; absent shows the key's translated default */
    name?: string;
  }[];
  /** The capabilities turned off for every role but owner */
  capabilities_off?: string[];
}

export interface RoleRef {
  key?: string;
  /** The display name; empty shows the key's translated default */
  name?: string;
  disabled?: boolean;
}

/** A session or an API key, without its secret */
export interface Token {
  id: number;
  kind: "session" | "api";
  label?: string;
  /** @format date-time */
  created_at: string;
  /**
   * Absent for an API key
   * @format date-time
   */
  expires_at?: string;
  /** @format date-time */
  last_used_at?: string;
  /** The client's address */
  last_used_from?: string;
  /**
   * The key a session was made from (POST /api/v1/login/key); absent for a
   * session of a sign-in and for a key
   */
  key_id?: number;
  /**
   * In a user's token list, true on the key that is the settings file's
   * MASSIMO_API_TOKEN, which is changed or removed there and not revoked
   * through the API; absent on any other
   */
  from_settings?: boolean;
  /**
   * The API key that made this key, as the bearer of its POST
   * /api/v1/users/{name}/tokens (AP KeyLife, D5-A); absent for a key made by a
   * session, the command line, the bootstrap or an integration's approval, and
   * for a session. A revoke of that key revokes this one
   */
  made_by?: number;
}

/**
 * The ids of the keys a revoke took with the token, the keys it made and theirs
 * (made_by), oldest first; [] for none
 */
export type TokenHeirs = number[];

export interface Me {
  /** How the server authenticates */
  mode?: "users" | "open" | "token" | "none";
  user?: User | null;
  role?: RoleRef | null;
  /**
   * What the caller may do, restart beside update or reboot, which include it;
   * every capability outside users mode
   */
  capabilities?: string[];
  /** The first owner can be created from here */
  setup?: boolean;
  /**
   * An open server kept open on purpose (the setting auth.keep_open): the web
   * UI does not ask for the first owner
   */
  kept_open?: boolean;
  token?: Token;
  /**
   * The registered integration whose key it is; null for any other key, and on
   * an open server, which does not look at the key (mode open)
   */
  integration?: {
    uuid?: string;
    /** Its name as the owner gives it, its own user's display name */
    name?: string;
    /** The name it reports */
    reported_name?: string;
    state?: string;
    instance_id?: string;
  } | null;
  /**
   * With X-MassimoHA-On-Behalf-Of: the integration's user the call acts for;
   * capabilities is then what the chain leaves. On an open server the header is
   * not read and nothing is attributed
   */
  acts_for?: {
    id?: string;
    name?: string;
    level?: "view" | "control" | "admin";
    linked?: boolean;
    system_generated?: boolean;
  };
}

/** One command of a restore plan */
export interface RestoreStep {
  /** The step as massimo restore prints it */
  what: string;
  /**
   * Sends radio commands, which cost budget; false for a Cube command (names,
   * NTP, time zone)
   */
  radio: boolean;
  /** The device the command addresses, when it has one */
  device?: string;
  /** The room woken up before the command, when there is one */
  room?: number;
  result?: RestoreStepResult;
}

/** The outcome of a step once it ran (GET …/restore only) */
export interface RestoreStepResult {
  ok?: boolean;
  /** The Cube refused the radiogram; present when true */
  discarded?: boolean;
  error?: string;
  budget?: Budget;
  /** @format date-time */
  time?: string;
}

export interface RepairPlan {
  action?: "reset" | "master" | "relink" | "unlink_relink" | "config" | "move" | "list";
  /** SHA-256 over the action and the lines; the run takes it */
  plan: string;
  steps: {
    what?: string;
    /** The device the command addresses */
    device?: string;
    /** The room woken up before the command */
    room?: number;
    /**
     * The queue resets error flags before the command: the device's, the
     * flagged members its room lines reach, the flagged devices its direct
     * lines address
     */
    reset?: boolean;
    /**
     * The command's lines as they go to the Cube, the wakeup and the queue's
     * resets not included
     */
    lines?: string[];
  }[];
  /** The s: lines */
  radiograms: number;
  /** About what they cost of the hourly radio budget, 1.25 % each */
  duty_cost_pct: number;
  /**
   * The memory slots they take, one each and a room radiogram one per member of
   * the room
   */
  slots: number;
  /**
   * Those held until the members' next wakeup, about ten minutes, a room
   * radiogram's but its addressee's
   */
  held_slots: number;
  /** The r: lines, those the queue sends before each command included; free */
  resets: number;
  wakeups: number;
  /** A metadata write, no radio */
  metadata: boolean;
  budget?: Budget;
  /** Why a run would be refused now; absent where it fits the budget */
  refused?: string;
  /**
   * Why the repair has nothing to send now, without plan and steps; its run is
   * refused with 409. A listing into a room the list lacks has details code
   * room_name_needed and room
   */
  nothing?: string;
  notes: string[];
  /** Not yet run on hardware */
  untested?: boolean;
  /**
   * What the repair names: the devices reset, the room's masters, the agreement
   * of a re-sent configuration, the rooms of a placement or listing
   */
  details?: Record<string, unknown>;
}

export interface RepairResult {
  ok?: boolean;
  action?: string;
  /** Where and why the repair stopped */
  error?: string;
  steps?: {
    what?: string;
    lines?: number;
    /** The lines the Cube accepted */
    accepted?: number;
    discarded?: boolean;
    error?: string;
  }[];
  budget?: Budget;
  /**
   * Radiograms were sent: the log's device change line says when the Cube's
   * free slots are back, or names the slots still held and the members left
   * flagged
   */
  confirmation?: "pending";
  /**
   * The devices reset whose flag the device list read after the resets still
   * shows
   */
  still_flagged?: string[];
}

export interface RestorePlan {
  /**
   * SHA-256 over the step list (texts and command lines); POST …/restore
   * takes it
   */
  plan: string;
  /**
   * The commands in the order they would be sent; empty when the Cube matches
   * the backup
   */
  steps?: RestoreStep[];
  /**
   * Differences a restore cannot write, such as devices that have to be paired
   * again
   */
  notes?: string[];
  /** Radiograms of all steps */
  radio_commands: number;
  /**
   * About what the radio commands will cost of the hourly radio budget, 1.25 %
   * each
   */
  duty_cost_pct: number;
  budget: Budget;
}

/** The last restore of a Cube; only state for none */
export interface RestoreState {
  id?: string;
  state?: "none" | "running" | "done" | "failed";
  /** The hash of the plan sent */
  plan?: string;
  /** @format date-time */
  started?: string;
  /**
   * Present once the restore ended
   * @format date-time
   */
  finished?: string;
  /**
   * The plan's steps, each with its result once it ran; a failed restore stops
   * at the failed step
   */
  steps?: RestoreStep[];
  /** Steps the Cube accepted */
  sent?: number;
  radio_commands?: number;
  /** Which step failed and why, for a failed restore */
  error?: string;
}

/** The restore field of restore_step and restore_done events */
export interface RestoreProgress {
  id?: string;
  /** Counts from 1 in the order of the plan's steps; restore_step only */
  step?: number;
  /** Steps in the plan */
  steps?: number;
  /** restore_step only */
  what?: string;
  ok?: boolean;
  /** Present when true */
  discarded?: boolean;
  error?: string;
  /** restore_done only */
  state?: "done" | "failed";
  /** Steps the Cube accepted; restore_done only */
  sent?: number;
}

export interface RestartInfo {
  /** Whether this caller's POST would restart the server now */
  available: boolean;
  /** Who starts the server again; absent when nobody would */
  by?: "systemd" | "launchd" | "windows" | "exit";
  /** Why the restart is not available */
  blocked?: string;
  /**
   * The settings file's variables that changed since the start and apply only
   * at the next one; names, never values
   */
  pending?: string[];
  /** The settings file serve reads */
  file?: string;
  /**
   * When the settings file was last read, at the start or since, also where it
   * did not parse, or was there but could not be read
   * @format date-time
   */
  read_at?: string;
  /**
   * What the last read of the settings file found the next start refuses;
   * absent where it found nothing, and at the start, which would have refused
   * it. The restart is offered all the same.
   */
  refused?: Refusal[];
}

/**
 * One thing the next start of serve refuses, in the start's order: a setting of
 * the settings file, or the file itself
 */
export interface Refusal {
  /**
   * The settings that changed since the start and that the refusing check
   * reads, by name; absent where the file itself does not parse, or is there
   * but cannot be read
   */
  settings?: string[];
  /**
   * The start's own text, which may quote a value, a secret's named by its
   * variable; for the file, its error naming the file and the line by its
   * number
   */
  error: string;
}

export interface RebootInfo {
  /** Whether this caller's POST would reboot the computer now */
  available: boolean;
  /** Who reboots; absent when nobody can */
  by?: "systemd" | "launchd" | "windows";
  /** Why the reboot is not available */
  blocked?: string;
  /**
   * When a reboot that waits, or has begun, is asked for
   * @format date-time
   */
  at?: string;
  /** The delay is over and the helper or the system was asked */
  begun?: boolean;
  /** Why the last reboot failed */
  error?: string;
}

export interface ReloadResult {
  /** The variables that changed in this read; names, never values */
  changed: string[];
  /** The variables that differ from the start and apply only at the next one */
  pending: string[];
  /** What the next start refuses of the settings now; empty for nothing */
  refused: Refusal[];
  /** @format date-time */
  read_at: string;
}

/** What System info shows, GET /api/v1/system */
export interface SystemInfo {
  /** The build version with the Go details, as /healthz has it */
  version: string;
  /**
   * When the server process started.
   * @format date-time
   */
  started_at: string;
  tls?: CertStatus;
  /**
   * The package manager that owns the binary (apt, brew), else what runs
   * the server: windows-service, systemd or launchd; other for a
   * terminal, a container or a supervisor massimo does not know.
   */
  install: string;
  /** The operating system, as Go names it: linux, darwin, windows. */
  os: string;
  /** The distribution's name from /etc/os-release; absent elsewhere. */
  os_name?: string;
  /** The processor, as Go names it: amd64, arm64, arm. */
  arch: string;
  hostname?: string;
  /** The caller's address as the server sees it. */
  client_ip: string;
  /**
   * The server's clock with its offset.
   * @format date-time
   */
  now: string;
  /**
   * The server's zone: TZ, else what /etc/localtime links to, else its
   * abbreviation.
   */
  time_zone?: string;
  /** The host's full name as hostname -f gives it. */
  fqdn?: string;
  /** The interfaces the API or a Cube proxy listens on. */
  interfaces: {
    name: string;
    mac?: string;
    addresses: {
      ip: string;
      /** The API listens on this address. */
      api?: boolean;
    }[];
  }[];
  /** The port the API listens on. */
  api_port?: number;
  /** The Cubes' proxy listeners, listening or not. */
  cube_proxies: {
    /**
     * The Cube's serial; absent until the Cube of a plain MASSIMO_CUBE_ADDRESS
     * reports it.
     */
    serial?: string;
    /**
     * The serial it answers discovery with: the Cube's proxy serial where set,
     * else the Cube's; absent where it answers no discovery.
     */
    discovery_serial?: string;
    addr: string;
    listening: boolean;
    /** The last try's error; absent while it listens. */
    error?: string;
    /**
     * The first failure; absent while it listens.
     * @format date-time
     */
    since?: string;
    /**
     * When it is tried again; absent while it listens.
     * @format date-time
     */
    next_try?: string;
    /** The tries so far; absent while it listens. */
    tries?: number;
  }[];
  /** The trusted proxy the request came through; absent otherwise. */
  proxy?: {
    /** Absent where no header says. */
    proto?: "https" | "http";
    host: string;
    /** Absent where neither a scheme nor a port is said. */
    port?: number;
    /**
     * The proxy's certificate as the last check read it; for https, absent
     * before the first.
     */
    certificate?: {
      source?: "proxy";
      names?: string[];
      /** @format date-time */
      not_after?: string;
      fingerprint?: string;
      self_signed?: boolean;
      issuer?: string;
      /** Valid for the host against the system's roots. */
      trusted: boolean;
      /** @format date-time */
      checked_at: string;
      /** Why the last check failed. */
      error?: string;
    };
  };
}

export interface StoreInfo {
  /** The store's file */
  file: string;
  /** The file's schema version */
  schema: number;
  /** The oldest schema version that still reads it */
  min_reader: number;
  /** The schema version this server is built for */
  binary: number;
  node: string;
  tenant: string;
  /** Rows per table */
  rows: Record<string, number>;
}

/** A proxy listener that does not listen, and is tried again */
export interface ProxyFailure {
  addr: string;
  /** The last try's error */
  error: string;
  /**
   * The first failure
   * @format date-time
   */
  since: string;
  /** @format date-time */
  next_try: string;
  tries?: number;
}

/**
 * A Cube with a fixed address that answered the latest discovery at another
 * one, neither it nor a proxy answering at its own; absent otherwise
 */
export interface FoundElsewhere {
  /**
   * Where it answers, with the configured address's port: the address a PUT
   * takes
   */
  address: string;
  /** The configured address */
  configured: string;
  /**
   * The run that first found it there
   * @format date-time
   */
  since: string;
}

export interface ConfigView {
  version: string;
  /** The settings file */
  file: string;
  file_found: boolean;
  data_dir: string;
  listen: string;
  tls: "off" | "files" | "self-signed" | "acme";
  /** The level and where it came from */
  log_level: string;
  variables: {
    name: string;
    /** Absent for a secret and for an unknown name */
    value?: string;
    /** The value is not shown: a secret, or an unknown name */
    secret?: boolean;
    /** Where the value came from, the environment or the settings file */
    source: string;
    /** A name Massimo does not know, perhaps a typo */
    unknown?: boolean;
  }[];
}

export interface UpdateInfo {
  /** The running version */
  current: string;
  /**
   * What the running build was released as: devel, nightly, alpha, beta, rc or
   * stable; absent for a build without the Makefile
   */
  flavour?: string;
  /**
   * The update channel: MASSIMO_UPDATE_CHANNEL, else the setting
   * update.channel, else the apt source's suite where apt owns the binary, else
   * the flavour
   */
  channel: string;
  /**
   * The suite of the apt source, where apt owns the binary; where it differs
   * from channel, the next update switches the source to the channel's suite
   */
  suite?: string;
  /**
   * The package manager that owns the binary (apt, brew); absent on a box
   * massimo install set up
   */
  manager?: string;
  /**
   * The version an update would install: the newest signed release the channel
   * takes, of its own flavour or a more stable one; where apt or brew owns the
   * binary, the newest its package source has, never newer than the signed
   * release
   */
  latest?: string;
  /** The newest signed release, where the package source has it not yet */
  released?: string;
  /**
   * Why the package source (apt's index, brew's formula) could not be read;
   * nothing is available then
   */
  source_error?: string;
  /**
   * A version the update helper found nothing to install for (up-to-date), held
   * back until a check made after it finds it in the package source
   */
  held?: string;
  /** The page of the newest signed release */
  release_url?: string;
  /** latest is newer than current, and not held back */
  available: boolean;
  /** @format date-time */
  checked_at: string;
  check_error?: string;
  /** POST would start an update */
  can_update: boolean;
  /**
   * Why an update cannot be started from the API (a package manager owning the
   * binary without a helper of its own, no token, no helper, on Windows and
   * under brew a listen address the helper cannot ask /healthz at, named by its
   * setting, a development build)
   */
  blocked?: string;
  helper?: UpdateStatus;
  /** The automatic update at night; absent without a store */
  auto?: {
    /** The setting update.auto */
    mode: "off" | "night";
    /** The setting update.auto_window, HH:MM-HH:MM in the server's time */
    window: string;
    /**
     * When the box will try: inside the window now, else at its next opening;
     * absent while no update is due or the version is skipped
     * @format date-time
     */
    next?: string;
    /**
     * What the next try waits for, where next is set: settings while the
     * server's next start refuses the settings file (GET /api/v1/restart's
     * refused); absent otherwise, a busy radio included
     */
    waits?: "settings";
    /**
     * The box's answer to the question (PUT /api/v1/update/answer), where it
     * names the version offered or a newer one
     */
    answer?: {
      version: string;
      answer: "tonight" | "skip";
      /** Who answered; absent for the owner's key */
      by?: {
        name?: string;
        display_name?: string;
      };
      /** @format date-time */
      at: string;
    };
    /**
     * The page asks a holder of update Install now, Tonight or Skip this
     * version: automatic updates on, an update due, no answer for it
     */
    ask: boolean;
  };
  /** The last ten updates, newest first; empty without a store */
  history: UpdateEntry[];
}

/**
 * An update: started in Massimo (by, to), or found at a start (outside);
 * completed by the next start with another version
 */
export interface UpdateEntry {
  /**
   * When it was started, or found at a start
   * @format date-time
   */
  at?: string;
  /**
   * The user who started it; absent for the owner's key and an update from
   * outside Massimo
   */
  by?: {
    name?: string;
    display_name?: string;
  };
  /** Massimo did not start it: apt, brew or a person on the box */
  outside?: boolean;
  /** The box's package manager (apt, brew), for an update from outside */
  manager?: string;
  /** The version that ran before */
  from?: string;
  /** The version asked for, where Massimo started it */
  to?: string;
  /**
   * The channel asked for, where Massimo started it; for an update from
   * outside, the one the box followed at the start that found it
   */
  channel?: string;
  /**
   * The version the next start ran, the one asked for or another apt chose;
   * absent while the update runs
   */
  reached?: string;
  /** @format date-time */
  reached_at?: string;
  /** The server started it itself, at night; by is absent then */
  auto?: boolean;
  /**
   * The update helper's outcome where the box did not stay on a new version,
   * rolled-back after reached ran: taken at the next read or the next update
   * started where the helper did not restart the server, else at the next start
   */
  result?: "failed" | "rolled-back" | "up-to-date";
}

/** The update helper's last run */
export interface UpdateStatus {
  state: "checking" | "installing" | "restarting" | "done" | "up-to-date" | "failed" | "rolled-back";
  from?: string;
  to?: string;
  channel?: string;
  message?: string;
  /** @format date-time */
  time: string;
}

export interface Error {
  error?: string;
  /**
   * Radio addresses of room members without state, when that caused the discard
   */
  no_state?: string[];
}

/** What the Cube last reported about its radio limits */
export interface Budget {
  /** Share of the hourly radio budget already used */
  duty_cycle_pct?: number;
  /** Free slots for unacknowledged radiograms (about 50) */
  free_memory_slots?: number;
  /** @format date-time */
  updated_at: string;
}

/** A Cube that answered discovery */
export interface FoundCube {
  serial: string;
  /**
   * What answered: a Cube, a massimo proxy (also one at an announced server's
   * address), or neither
   */
  kind: "cube" | "proxy" | "unknown";
  /**
   * A proxy's: the serial of the Cube with its radio address, served here or
   * found; absent where none is known
   */
  serves?: string;
  /**
   * The massimo server that serves it, announced on the LAN: the one at a
   * proxy's address, or the one a proxy of a Cube runs on; absent where none
   * matched
   */
  host?: {
    /** Its instance name */
    name: string;
    /** The url its announcement gives, else http(s)://<address>:<port> */
    url: string;
  };
  configured?: boolean;
  /**
   * True where address lies in none of this machine's networks, as a Cube
   * without a DHCP lease on 192.168.0.222 does; absent otherwise, and on a
   * proxy
   */
  other_network?: boolean;
  /**
   * The IP it answered from, its own where a massimo proxy answers for it too
   */
  address: string;
  /** From the host's ARP cache; absent when unknown */
  mac?: string;
  rf_address: string;
  firmware: string;
  /**
   * Whether the Cube takes its address by DHCP, from its answer to the c
   * request in this server run's latest discovery that had one; absent until it
   * has answered c
   */
  dhcp?: boolean;
  /**
   * The gateway the Cube uses, from its answer to the N request in this server
   * run's latest discovery that had one; absent until then
   */
  gateway?: string;
  /** The netmask the Cube uses, as gateway */
  netmask?: string;
  /** The DNS servers the Cube uses, as gateway */
  dns?: string[];
  /**
   * The other addresses that answered for the Cube's serial in the latest run:
   * massimo proxies (docs/proxy.md); absent when none did
   */
  proxies?: string[];
  /**
   * A Cube that is not configured: the removed rows of its serial in the store,
   * newest first, one of which POST /api/v1/cubes can restore; absent where
   * there are none, and on a proxy
   */
  removed?: {
    /**
     * The row's, for POST /api/v1/cubes's restore
     * @format uuid
     */
    uuid: string;
    /** The name it had; empty where it had none */
    name: string;
    /**
     * When it was removed
     * @format date-time
     */
    removed_at: string;
  }[];
  /**
   * In GET /api/v1/cubes: the backups the store keeps of the serial's row,
   * which GET …/backups lists while no runtime serves it; 0 without a row;
   * absent in the answer of a discovery
   */
  backups?: number;
  /**
   * When the server first saw it
   * @format date-time
   */
  found_at?: string;
  /**
   * Its latest answer
   * @format date-time
   */
  last_seen: string;
}

/** A run of discovery, as POST /api/v1/cubes/discover answers it */
export interface Discovery {
  /** @format date-time */
  ran_at: string;
  /**
   * Every Cube and massimo proxy that answered, configured or not; empty where
   * none did
   */
  found: FoundCube[];
}

/**
 * The certificate the server serves, as /healthz and GET /api/v1/system give it
 * as tls; absent without TLS
 */
export interface CertStatus {
  /** Where the certificate comes from: files, self-signed, or acme. */
  source?: string;
  /** The certificate's names and addresses. */
  names?: string[];
  /** @format date-time */
  not_after: string;
  /** The SHA-256 of the certificate, as browsers show it. */
  fingerprint?: string;
  self_signed: boolean;
  /** Set while something needs the owner. */
  warning?: string;
}

export interface Cube {
  serial: string;
  /**
   * User-friendly name from the store (seeded from MASSIMO_CUBE_<SN>_NAME),
   * when set
   */
  name?: string;
  address: string;
  /** Always true here; found Cubes are FoundCube */
  configured?: boolean;
  /** Where the configuration comes from; absent without a store */
  source?: "env" | "ui" | "flag";
  /**
   * The settings file's lines for this Cube whose values differ from the
   * store's, which wins
   */
  file_differs?: FileDifference[];
  /**
   * The backups the store keeps of the Cube (GET …/backups); 0 for a Cube
   * without a row in the store, and without a store
   */
  backups: number;
  /**
   * The stored address; empty: from discovery (address is where it connects
   * now)
   */
  configured_address: string;
  follow_discovery: boolean;
  /** The configured proxy address; empty: the default */
  proxy_address?: string;
  proxy_serial?: string;
  /** The proxy shows clients the rooms' virtual wall thermostats */
  proxy_virtual: boolean;
  /** The addresses the Cube's proxy listens on now */
  proxy_listening?: string[];
  /**
   * The Cube's proxy listeners that do not listen, tried again; absent where
   * none
   */
  proxy_failing?: ProxyFailure[];
  /** The hidden list (radio addresses), besides room 255 */
  hidden: string[];
  /** From discovery, once it saw the Cube */
  mac?: string;
  /**
   * When the Cube last answered discovery
   * @format date-time
   */
  last_seen?: string;
  /**
   * The host discovery last found the Cube at; differs from address where the
   * server connects through a proxy or to a fixed address the Cube has left
   */
  found_address?: string;
  found_elsewhere?: FoundElsewhere;
  /**
   * True where the address the server connects to lies in none of this
   * machine's networks: it reaches the Cube only through a router; absent
   * otherwise, and for a host name
   */
  other_network?: boolean;
  /**
   * The Cube's memory slots held, fewer than 5 free (level warn) or fewer than
   * 2 (error), at two readings an hour apart with nothing of the server's in
   * flight: radiograms held for devices that do not answer, which a reboot of
   * the Cube drops; absent otherwise (docs/api-v1.md, GET /api/v1/cubes)
   */
  slots_low?: {
    level: "warn" | "error";
    /**
     * The first reading below 5 of the run
     * @format date-time
     */
    since: string;
    /**
     * The first reading below 2, for error
     * @format date-time
     */
    full_since?: string;
    /** The free slots at the last reading */
    free_slots: number;
    /**
     * When the log's slots event of the level was given
     * @format date-time
     */
    logged: string;
  };
  /**
   * The Cube's visible devices with a problem (a communication or link error, a
   * low battery, a window open), each with its room's name; absent where none
   */
  problems?: (Device & {
    /** The device's room's name */
    room?: string;
  })[];
  /** The server is connected to the Cube and has its complete greeting */
  connected: boolean;
  /**
   * How the server stands with a configured Cube beyond connected
   * (docs/api-v1.md, GET /api/v1/cubes)
   */
  link: {
    /**
     * held: a lost connection held open; stale: the Cube answers discovery but
     * refuses a new connection while it holds the server's old one; busy: the
     * same, another client holding it
     */
    state: "connected" | "held" | "stale" | "busy" | "rebooting" | "offline";
    /**
     * Since when: the loss of a held connection, the first refused dial
     * @format date-time
     */
    since?: string;
    /**
     * The hold ends then at the latest
     * @format date-time
     */
    until?: string;
  };
  firmware?: string;
  rf_address?: string;
  budget: Budget;
  /**
   * Radiograms sent by the Cube and not yet acknowledged by a device (memory
   * slots in use): all of them when no slot is free, 0 until the Cube has
   * reported its budget
   */
  pending_radiograms: number;
  /** @format date-time */
  updated: string;
  /**
   * When the server first heard from the Cube; a device value received at that
   * time was already there and may be older
   * @format date-time
   */
  observed_since?: string;
  rooms?: number;
  devices?: number;
  /** Commands waiting in the queue */
  queued?: number;
  /**
   * The Cube's clock in its greeting at the last connect, its own time zone, to
   * the minute
   */
  cube_time?: string;
  /**
   * When the server read cube_time
   * @format date-time
   */
  cube_time_at?: string;
}

/** The fields of a Cube's configuration that PUT and POST change */
export interface CubeChange {
  name?: string;
  /** host or host:port; empty: from discovery */
  address?: string;
  /** The address follows the Cube's discovery answers */
  follow_discovery?: boolean;
  /**
   * The server's listener for this Cube, host[:port]; empty: :62910 with a
   * single Cube
   */
  proxy_address?: string;
  /** The serial in discovery replies; empty: the Cube's */
  proxy_serial?: string;
  /**
   * The proxy shows clients the rooms' virtual wall thermostats in place of the
   * real wall thermostats; off by default
   */
  proxy_virtual?: boolean;
  /** Radio addresses of devices to hide, besides those in room 255 */
  hidden?: string[];
}

export interface Setting {
  /** The store's value, or the default; durations as 30m, 24h, 0 for off */
  value: string;
  default?: string;
  /** The store holds a value */
  set: boolean;
  /** What this run uses; a serve flag wins for one run */
  in_effect?: string;
  applies?: "now" | "restart";
  read_only?: boolean;
  /**
   * What decides this run's value instead of the setting: -announce or
   * MASSIMO_ANNOUNCE (announce), -poll, -refresh, -discover-interval or
   * -stale-after (the intervals)
   */
  fixed_by?: string;
}

export interface FileDifference {
  field: "name" | "address" | "proxy_address" | "proxy_serial" | "hidden";
  variable: string;
  /** The file's value; a list of radio addresses for hidden */
  file: unknown;
  /** The store's value, in effect; a list for hidden */
  store: unknown;
}

export interface CubeDetail extends Cube {
  config?: CubeConfig;
  room_list?: Room[];
}

export interface CubeConfig {
  portal_enabled?: boolean;
  portal_url?: string;
  push_button_up?: number;
  push_button_down?: number;
  tz_winter?: TimeZoneRule;
  tz_summer?: TimeZoneRule;
}

export interface TimeZoneRule {
  name?: string;
  month?: number;
  weekday?: number;
  hour?: number;
  offset_seconds?: number;
}

export interface Room {
  id: number;
  name: string;
  /**
   * The room's uid, kept for the room's life and never given to another room;
   * absent before the server has read the room
   */
  room_uid?: string;
  /**
   * Every device of the room has reported since the Cube restarted, so the Cube
   * accepts room commands
   */
  ready: boolean;
  /** A device of the room is stale; present when true */
  stale?: boolean;
  /**
   * The radio address of the thermostat whose state is the room's, the first of
   * its virtual wall thermostat's sources.setpoint (RoomMajority.D9, D19-A):
   * one of those whose state more than half show, else the one whose mode or
   * setpoint changed last, else the first of the room's one order (its master,
   * its wall thermostat, its radiator thermostats); during a boost the same
   * over those that do not boost; where no thermostat has a state, the first of
   * that order, as the room's commands name it; absent for a room without a
   * thermostat
   */
  thermostat?: string;
  /**
   * The room's comfort temperature, as GET …/rooms/{id}/config gives it: what
   * more than half of its thermostats store, else the first of its order's;
   * absent for a room without a thermostat
   */
  comfort_temp?: number;
  /** The room's eco temperature, as comfort_temp */
  eco_temp?: number;
  /**
   * The room's lowest setpoint, as comfort_temp; a client offers the room's
   * setpoints within min_setpoint and max_setpoint
   */
  min_setpoint?: number;
  /** The room's highest setpoint, as comfort_temp */
  max_setpoint?: number;
  devices: Device[];
  /**
   * The findings of the Cube's C lines against its room list that concern the
   * room, and of its members that differ (docs/api-v1.md, "The Cube's lines
   * against its room list"); absent where none
   */
  mismatches?: Mismatch[];
  confirmation?: Confirmation;
}

/**
 * A write not confirmed yet: the device, or members of the room, do not show
 * what it set. Present while one is open
 */
export interface Confirmation {
  /**
   * pending until five minutes after the Cube's answer, then unconfirmed until
   * the devices show it or a newer write of the same kind replaces it; a room
   * setpoint sent once more is pending again for five minutes after the
   * re-send's answer
   */
  state: "pending" | "unconfirmed";
  /**
   * When the Cube took the oldest write still open
   * @format date-time
   */
  since: string;
  /**
   * The values not shown yet: mode, setpoint, until, locked and display_actual
   * of the state; the configuration's by their names (comfort_temp …
   * valve_offset_pct); program.<day> for a day of the week programme,
   * program.<day>.2 for a long day's second radiogram
   */
  fields: string[];
  /** A room's: the radio addresses of its members that do not show them */
  devices?: string[];
}

/**
 * A difference between a C line and the room list, or among a room's members,
 * that the server found (docs/api-v1.md, "The Cube's lines against its room
 * list")
 */
export interface Mismatch {
  finding: "room" | "unlisted" | "no_config" | "type" | "master" | "programme" | "temperatures";
  /**
   * The device concerned, a room's master for master; absent for a master of
   * address 000000
   */
  device?: string;
  /** The device's name in the room list */
  name?: string;
  /**
   * The room concerned: the room list's where it has the device, else its C
   * line's
   */
  room: number;
  room_name?: string;
  /**
   * The room of the device's C line (room, unlisted), of the master's (master
   * other_room)
   */
  cube_room?: number;
  cube_room_name?: string;
  /** The room the room list has the device in (room, no_config) */
  list_room?: number;
  list_room_name?: string;
  cube_type?: DeviceType;
  list_type?: DeviceType;
  /** A master's finding */
  why?: "no_device" | "other_room" | "not_thermostat";
  /**
   * When the server first found it
   * @format date-time
   */
  since: string;
}

export type DeviceType = "cube" | "radiator_thermostat" | "radiator_thermostat_plus" | "wall_thermostat" | "shutter_contact" | "eco_switch";

export type Mode = "auto" | "manual" | "vacation" | "boost";

/**
 * The type of the Cube's last radiogram to the device that failed, byte 4 of
 * its entry; present only while error is set
 */
export interface FailedRadiogram {
  /** The radiogram type's code, 3 for TimeInformation */
  code: number;
  /**
   * The original software's name of the type (its FrameType enum,
   * docs/cube-protocol.md); absent for a code it lacks
   */
  name?: string;
}

/** The device's last report; absent until it reported once */
export interface State {
  mode?: Mode;
  setpoint?: number;
  /** Vacation end, YYYY-MM-DD HH:MM */
  until?: string;
  /**
   * The last measured temperature the device reported, kept while its entries
   * carry none; received.actual_temp says when it appeared
   */
  actual_temp?: number;
  valve_pct?: number;
  window_open?: boolean;
  /**
   * The battery flag as the Cube shows it now; the device's battery has the
   * level the server keeps
   */
  battery_low?: boolean;
  /**
   * The communication error the Cube reports: its last radiogram to the device
   * failed; it stays until reset (r:) or a Cube restart
   */
  error?: boolean;
  failed_radiogram?: FailedRadiogram;
  /**
   * The link error the device reports: its radio communication with another
   * MAX! device of its room is disturbed (the original software's
   * transmitError)
   */
  link_error?: boolean;
  /** Key lock active on the device; present when true */
  panel_locked?: boolean;
  /**
   * A virtual wall thermostat's alone: false while the room's thermostats
   * disagree on mode, setpoint or until
   */
  consistent?: boolean;
}

export interface Device {
  rf_address: string;
  type: DeviceType;
  name: string;
  room_id: number;
  serial?: string;
  /** Paired but not assigned to a room */
  unlisted?: boolean;
  /**
   * The Cube holds state for the device (it transmitted since the Cube
   * restarted)
   */
  reported: boolean;
  state?: State;
  /**
   * The Cube marks the device's entry out of date, as after some minutes of
   * silence: reported is false and state absent, last_known holds its last
   * report. Present when true
   */
  out_of_date?: boolean;
  last_known?: State;
  /**
   * Per value of state (same names), when the server saw its current value
   * appear in the Cube's device list. The Cube keeps no times; a repeated value
   * keeps its time, and a value already there when the server connected carries
   * the Cube's observed_since. Present with state.
   */
  received?: Record<string, string>;
  /**
   * When the device's entry in the Cube's device list last changed; present
   * with state
   * @format date-time
   */
  last_seen?: string;
  /**
   * An open window's times, present while state.window_open is true: when the
   * server saw it open, and when it counts as open too long, as a warning and
   * as an alert (the settings window_warn_after and window_alert_after).
   */
  window?: {
    /** @format date-time */
    open_since: string;
    /** @format date-time */
    warn_at: string;
    /** @format date-time */
    alert_at: string;
  };
  /**
   * A reported device's battery level, from the history of its flag: weak once
   * the flag was seen, low once it stayed 15 minutes; ok again after a long
   * valve move without it (weak) or an hour without it (low), or at once when
   * someone marks new batteries (POST …/devices/{rf}/battery). Absent for a
   * virtual wall thermostat and a device without state
   */
  battery?: "ok" | "weak" | "low";
  /**
   * A radiator or wall thermostat's comfort temperature, from its configuration
   * (C line); absent for another device and where the Cube sent none
   */
  comfort_temp?: number;
  /**
   * A radiator or wall thermostat's eco temperature, from its configuration (C
   * line); absent for another device and where the Cube sent none
   */
  eco_temp?: number;
  /**
   * Radiator or wall thermostat whose entry has not changed for its stale
   * threshold (stale_after, 50 hours, or stale_after_wall, 24 hours): out of
   * range, flat battery, or just quiet. Present when true. A virtual wall
   * thermostat is stale when every source of its actual_temp is
   */
  stale?: boolean;
  /**
   * A room's virtual wall thermostat, which the server computes from the room's
   * devices; present when true
   */
  virtual?: boolean;
  /** A virtual wall thermostat's room's uid */
  room_uid?: string;
  /**
   * A virtual wall thermostat's alone: the radio addresses its actual_temp came
   * from, those its mode came from and those its setpoint and until came from
   */
  sources?: {
    actual_temp?: string[];
    /**
     * Those its mode came from by the room's one order: those that show it, the
     * one of the newest change, or the one of the order; the boosting ones
     * during a boost
     */
    mode?: string[];
    /**
     * Those its setpoint and until came from by the room's one order, the one
     * whose state it shows first, which the room entry's thermostat names;
     * during a boost from the thermostats that do not boost
     */
    setpoint?: string[];
  };
  confirmation?: Confirmation;
  /**
   * The findings of the device's C line against the room list, and of its
   * room's members, that name it (docs/api-v1.md, "The Cube's lines against its
   * room list"); absent where none
   */
  mismatches?: Mismatch[];
}

/** Every field optional; merged into the device's current configuration */
export interface ConfigWrite {
  /** 4.5 to 30.5 in steps of 0.5 */
  comfort_temp?: number;
  eco_temp?: number;
  max_setpoint?: number;
  min_setpoint?: number;
  /** -3.5 to 3.5 in steps of 0.5; per device only */
  temp_offset?: number;
  window_open_temp?: number;
  /** 0 to 60 in steps of 5 */
  window_open_minutes?: number;
  /** 0 to 30 in steps of 5, or 60 */
  boost_minutes?: number;
  /** 0 to 100 in steps of 5 */
  boost_valve_pct?: number;
  decalc_day?: "monday" | "tuesday" | "wednesday" | "thursday" | "friday" | "saturday" | "sunday";
  decalc_hour?: number;
  max_valve_pct?: number;
  valve_offset_pct?: number;
  /** Wall thermostats only, per device only */
  display_actual?: boolean;
}

export interface DeviceResult {
  rf_address?: string;
  name?: string;
  ok?: boolean;
  discarded?: boolean;
  error?: string;
}

export interface RoomConfig {
  id?: number;
  name?: string;
  /**
   * The first thermostat of the room's one order that stores the room's
   * temperatures, else the first of the order; absent for a room without a
   * thermostat
   */
  source?: string;
  comfort_temp?: number;
  eco_temp?: number;
  max_setpoint?: number;
  min_setpoint?: number;
  window_open_temp?: number;
  window_open_minutes?: number;
  boost_minutes?: number;
  boost_valve_pct?: number;
  decalc_day?: string;
  decalc_hour?: number;
  max_valve_pct?: number;
  valve_offset_pct?: number;
  devices?: {
    rf_address?: string;
    type?: DeviceType;
    name?: string;
    temp_offset?: number;
    display_actual?: boolean;
  }[];
}

export interface SwitchPoint {
  temp?: number;
  until?: string;
}

/** Switch points per weekday; the last point of a day ends at 24:00 */
export interface WeekProgram {
  monday?: SwitchPoint[];
  tuesday?: SwitchPoint[];
  wednesday?: SwitchPoint[];
  thursday?: SwitchPoint[];
  friday?: SwitchPoint[];
  saturday?: SwitchPoint[];
  sunday?: SwitchPoint[];
}

export interface ThermostatConfig {
  comfort_temp?: number;
  eco_temp?: number;
  max_setpoint?: number;
  min_setpoint?: number;
  temp_offset?: number;
  window_open_temp?: number;
  window_open_minutes?: number;
  boost_minutes?: number;
  boost_valve_pct?: number;
  decalc_day?: string;
  decalc_hour?: number;
  max_valve_pct?: number;
  valve_offset_pct?: number;
  week_program?: WeekProgram;
}

export interface WallThermostatConfig {
  comfort_temp?: number;
  eco_temp?: number;
  max_setpoint?: number;
  min_setpoint?: number;
  temp_offset?: number;
  window_open_temp?: number;
  boost_minutes?: number;
  boost_valve_pct?: number;
  /** The display shows the measured temperature instead of the setpoint */
  display_actual?: boolean;
  week_program?: WeekProgram;
}

/** A device that joined during pairing, from the Cube's N line */
export interface NewDevice {
  type: DeviceType;
  rf_address: string;
  serial: string;
}

export interface PairingState {
  active: boolean;
  /** @format date-time */
  started?: string;
  /**
   * When pairing ends at the latest
   * @format date-time
   */
  until: string;
  /**
   * When the last pairing ended; absent while active or before the first
   * @format date-time
   */
  ended?: string;
  /** Devices that joined during the current or last pairing */
  paired: NewDevice[];
}

export interface IntegrationRequest {
  kind: "homeassistant";
  /** The installation's name (Home Assistant's location_name) */
  name: string;
  /** The installation id */
  instance_id: string;
  url?: string;
  version?: string;
}

export interface Integration {
  uuid: string;
  kind: string;
  /**
   * Its name as the owner gives it (PUT), its own user's display name; it
   * follows reported_name while it is the name reported before. A request's is
   * the name it reported.
   */
  name: string;
  /**
   * The name the integration reports, when it asks and when a request is
   * attached to it
   */
  reported_name: string;
  state: "pending" | "active" | "disabled";
  instance_id: string;
  /** An installation id a call came with, not accepted yet */
  pending_instance?: string;
  url?: string;
  version?: string;
  /** The key's maximum, within the role integration */
  max_caps?: string[];
  /** A request's short code */
  request_code?: string;
  /**
   * Until when a request waits, or an approved integration may collect its key;
   * absent once collected
   * @format date-time
   */
  request_expires?: string;
  /** The address the request came from */
  request_remote?: string;
  /** @format date-time */
  key_issued_at?: string;
  /** @format date-time */
  created_at: string;
  /** The last look at the LAN saw its installation id */
  seen?: boolean;
  /** Its users, in GET /api/v1/integrations/{uuid} alone */
  users?: IntegrationUser[];
}

export interface IntegrationUser {
  /** Its id at the integration, or system */
  id: string;
  /** Its name there, from its last call */
  name: string;
  /**
   * Its chain, <the integration's name> › <its user's display name>, with ",
   * as <login name>" where linked
   */
  display: string;
  /** The user its calls act as */
  user: string;
  /** The user made at its first call */
  own_user: string;
  linked: boolean;
  system_generated?: boolean;
  last_level?: "view" | "control" | "admin";
  /** @format date-time */
  last_used_at?: string;
  /**
   * A Massimo user of the same name to link it to; absent where linked or none
   * matches
   */
  proposal?: string;
}

export interface ProgramWithTag extends WeekProgram {
  /**
   * The device the programme comes from: for a room, the first of its one order
   * whose whole week is the room's, else the first of the order
   */
  source?: string;
  /**
   * The tag over every thermostat of the room's programme, as If-Match takes it
   */
  etag?: string;
  /** A programme written and not yet in the devices' configurations */
  pending?: boolean;
  /** False while the room's thermostats have different programmes */
  program_consistent?: boolean;
}

export interface DeviceDetail extends Device {
  firmware?: number;
  thermostat?: ThermostatConfig;
  wall_thermostat?: WallThermostatConfig;
  /** A virtual wall thermostat's alone */
  settings?: {
    /**
     * How a room without a wall thermostat takes its temperature from its
     * radiator thermostats
     */
    temp_method?: "median" | "mean";
    /** The address the owner gave it; absent for its room number */
    rf_address?: string;
  };
}

export interface Setpoint {
  /**
   * boost opens the valves by the thermostats' boost settings for their boost
   * time, then they return to the mode they had
   */
  mode: "auto" | "manual" | "vacation" | "boost";
  /**
   * Required for manual and vacation; optional for auto; ignored by the devices
   * for boost
   */
  temp?: number;
  /** Vacation end, YYYY-MM-DD HH:MM on a half hour; required for vacation */
  until?: string;
}
